// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: a deposit that is at least 1 ether, but not so large that
        // c's own initial balance (0) plus deposit cannot be drained below MinSum in M.
        amount = bound(amount, 1 ether, 100 ether);
        unlockTime = bound(unlockTime, 0, block.timestamp);

        // Adversarial counterparty: re-enters Collect exactly once from the repay callback.
        Reenterer attacker = new Reenterer(address(c), amount);
        vm.deal(address(attacker), amount);

        vm.prank(address(attacker));
        c.Put{value: amount}(unlockTime);

        // Advance time so the unlock condition passes.
        vm.warp(block.timestamp + 1);

        // Actor withdraws, causing c to call back into attacker and (only in M) re-enter Collect.
        vm.prank(address(attacker));
        c.Collect(amount);

        uint256 minSum = c.MinSum();
        assertTrue(address(c).balance >= minSum);
    }
}

contract Reenterer {
    address payable private target;
    uint256 private withdrawAmount;
    bool private entered;

    constructor(address _target, uint256 _amount) payable {
        target = payable(_target);
        withdrawAmount = _amount;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            W_WALLET(target).Collect(withdrawAmount);
        }
    }
}
